CREATE TABLE g_budgetAlertPolicies (id TEXT PRIMARY KEY,revision TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE g_budgetAlerts (id TEXT PRIMARY KEY,revision TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),engagement_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.engagementId')) STORED NOT NULL REFERENCES g_engagements(id),phase_key TEXT GENERATED ALWAYS AS (json_extract(data,'$.phaseKey')) STORED NOT NULL,metric TEXT GENERATED ALWAYS AS (json_extract(data,'$.metric')) STORED NOT NULL,threshold INTEGER GENERATED ALWAYS AS (json_extract(data,'$.threshold')) STORED NOT NULL,UNIQUE(engagement_id,phase_key,metric,threshold));
CREATE TRIGGER g_immutable_budget_alert BEFORE UPDATE ON g_budgetAlerts BEGIN SELECT RAISE(ABORT,'immutable_budget_alert'); END;
